def parse(self, response):
    items = response.css('ul li')
    for item in items:
        title = item.css('a::text').get()
        link = item.css('a::attr(href)').get()
        yield {
            'title': title,
            'link': response.urljoin(link) if link else None
        }

async def parse_list(page):
    items = await page.query_selector_all('ul li')
    for item in items:
        detail_link = await item.query_selector_eval('a', 'a => a.href')
        title = await item.query_selector_eval('.title', 'el => el.innerText')
        yield {'title': title, 'detail_link': detail_link}

def parse(self, response):
    rows = response.css('table tbody tr')
    for row in rows:
        item = {}
        item['study_title'] = row.css('td:nth-child(1)::text').get(default='').strip()
        item['study_id'] = row.css('td:nth-child(2)::text').get(default='').strip()
        item['status'] = row.css('td:nth-child(3)::text').get(default='').strip()
        item['phase'] = row.css('td:nth-child(4)::text').get(default='').strip()
        item['study_type'] = row.css('td:nth-child(5)::text').get(default='').strip()
        item['start_date'] = row.css('td:nth-child(6)::text').get(default='').strip()
        item['completion_date'] = row.css('td:nth-child(7)::text').get(default='').strip()
        detail_link = row.css('td a[href^="https://pubmed.ncbi.nlm.nih.gov/"]::attr(href)').get()
        if detail_link:
            yield response.follow(detail_link, callback=self.parse_detail, meta={'item': item})
        else:
            yield item
